import Foundation

/// Represents a structured action plan generated by the Apple Foundation Model.
///
/// Contains the model's internal reasoning (`thought`), the exact shell command
/// to be executed in the terminal (`command`), and a concise human-readable explanation (`explanation`).
public struct GitPlan: Codable, Equatable {
    /// The internal chain-of-thought analysis explaining why the command was chosen.
    public let thought: String

    /// The exact shell command string (e.g. `git add . && git commit -m "..."`).
    public let command: String

    /// A brief summary of the command's intent.
    public let explanation: String

    /// Optional raw text returned by the model before JSON extraction.
    public var rawResponse: String? = nil

    /// Memberwise initializer for `GitPlan`.
    public init(thought: String, command: String, explanation: String, rawResponse: String? = nil) {
        self.thought = thought
        self.command = command
        self.explanation = explanation
        self.rawResponse = rawResponse
    }
}

/// Abstract contract defining the capabilities required for a Foundation Model client.
///
/// By conforming to this protocol, `AppleFMClient` can be substituted with mock implementations
/// in unit tests without requiring a real neural engine or local model daemon.
public protocol FMClientProtocol {
    /// Checks whether the model backend (CLI daemon or HTTP server) is available and operational.
    func isAvailable() -> Bool

    /// Queries the model to generate a Git command plan based on the user's task and current repository state.
    func planAction(task: String, gitContext: String, sessionHistory: String?) async throws -> GitPlan

    /// Queries the model to diagnose a command execution failure and produce a corrected recovery command.
    func planRecovery(task: String, failedCommand: String, exitCode: Int32, output: String, gitContext: String) async throws -> GitPlan

    /// Prompts the model to synthesize raw terminal output into a friendly, readable user summary.
    func synthesizeOutput(task: String, executedCommand: String, exitCode: Int32, rawTerminalOutput: String) async throws -> String
}

/// Default convenience overload for `planAction` without explicit session history.
public extension FMClientProtocol {
    func planAction(task: String, gitContext: String) async throws -> GitPlan {
        return try await planAction(task: task, gitContext: gitContext, sessionHistory: nil)
    }
}

/// Client interface to Apple Foundation Models supporting dual execution modes:
/// 1. **Persistent Server Mode**: Communicates over local HTTP with `fm serve` (`http://127.0.0.1:1976/v1/chat/completions`).
/// 2. **CLI Daemon Fallback**: Spawns `/usr/bin/fm respond` with JSON schema enforcement if the server is offline.
public class AppleFMClient: FMClientProtocol {
    /// File path to the system `fm` binary.
    public let binaryPath: String

    /// Base URL of the local completions API server (default: `http://127.0.0.1:1976`).
    public let serverBaseURL: String?

    /// Cached on-disk file path to the JSON schema used for structured output generation.
    private var schemaPath: String?

    /// System instructions guiding the model to output valid Git commands matching the schema.
    public static let defaultInstructions = """
    You are an expert autonomous Git engineering agent.
    Your mission is to translate user goals or errors into exact, correct Git commands.

    Rules:
    1. The 'thought' field MUST explain your reasoning and diagnosis.
    2. The 'command' field MUST contain the exact command to run in the terminal (e.g., 'git add . && git commit -m "feat: add login"').
    3. Chain multiple commands with '&&' if multiple steps are needed.
    4. Every command must invoke 'git' or safe shell utilities needed for git operations.
    5. If the task is already satisfied or cannot be done, explain in 'thought' and 'explanation' and set command to '' (empty string).
    6. For error recovery: diagnose the root cause carefully (e.g. untracked conflicts, detached HEAD, missing upstream, existing branch) and generate the precise fix.
    """

    /// System instructions for Step 2: translating raw terminal stdout/stderr into clean user summaries.
    public static let outputSynthesisInstructions = """
    You are an assistant reporting Git command execution results to the user.
    Given the user's original task and the raw terminal output from the executed command:
    Synthesize a clean, user-friendly explanation of what was done and the result.
    Keep it concise (1-2 sentences). Do not use markdown code fences.
    """

    /// Initializes an `AppleFMClient` instance.
    ///
    /// - Parameters:
    ///   - binaryPath: Path to the Apple `fm` CLI (default: `/usr/bin/fm`).
    ///   - serverBaseURL: Base URL for `fm serve` (default: `http://127.0.0.1:1976`).
    public init(binaryPath: String = "/usr/bin/fm", serverBaseURL: String? = "http://127.0.0.1:1976") {
        self.binaryPath = binaryPath
        self.serverBaseURL = serverBaseURL
    }

    /// Checks if either the persistent HTTP server or the system CLI daemon is operational.
    public func isAvailable() -> Bool {
        if isServerOnline() {
            return true
        }
        guard FileManager.default.fileExists(atPath: binaryPath) else { return false }
        let process = Process()
        process.executableURL = URL(fileURLWithPath: binaryPath)
        process.arguments = ["available"]
        let pipe = Pipe()
        process.standardOutput = pipe
        do {
            try process.run()
            process.waitUntilExit()
            let data = pipe.fileHandleForReading.readDataToEndOfFile()
            let str = String(data: data, encoding: .utf8) ?? ""
            return process.terminationStatus == 0 && str.contains("System model available")
        } catch {
            return false
        }
    }

    /// Pings the `GET /health` endpoint of `fm serve` with a tight timeout to detect server availability.
    public func isServerOnline() -> Bool {
        guard let base = serverBaseURL, let url = URL(string: "\(base)/health") else { return false }
        var request = URLRequest(url: url)
        request.timeoutInterval = 0.5

        let semaphore = DispatchSemaphore(value: 0)
        var online = false

        URLSession.shared.dataTask(with: request) { data, response, _ in
            if let http = response as? HTTPURLResponse, http.statusCode == 200 {
                online = true
            }
            semaphore.signal()
        }.resume()

        _ = semaphore.wait(timeout: .now() + 0.6)
        return online
    }

    /// Assembles an OpenAI-compatible JSON request body for chat completions.
    private func buildChatRequestBody(systemPrompt: String, userPrompt: String) throws -> Data {
        let body: [String: Any] = [
            "model": "system",
            "stream": false,
            "messages": [
                ["role": "system", "content": systemPrompt],
                ["role": "user", "content": userPrompt]
            ]
        ]
        return try JSONSerialization.data(withJSONObject: body)
    }

    /// Parses the raw JSON response payload from the `/v1/chat/completions` server endpoint.
    private func parseServerResponse(data: Data?) -> String? {
        guard let data = data,
              let json = try? JSONSerialization.jsonObject(with: data) as? [String: Any],
              let choices = json["choices"] as? [[String: Any]],
              let first = choices.first,
              let message = first["message"] as? [String: Any],
              let content = message["content"] as? String else {
            return nil
        }
        return content
    }

    /// Sends a completion request to `fm serve` via HTTP POST.
    private func queryServer(systemPrompt: String, userPrompt: String) throws -> String? {
        guard isServerOnline(), let base = serverBaseURL, let url = URL(string: "\(base)/v1/chat/completions") else {
            return nil
        }

        var request = URLRequest(url: url)
        request.httpMethod = "POST"
        request.addValue("application/json", forHTTPHeaderField: "Content-Type")
        request.timeoutInterval = 30.0
        request.httpBody = try buildChatRequestBody(systemPrompt: systemPrompt, userPrompt: userPrompt)

        let semaphore = DispatchSemaphore(value: 0)
        var resultText: String? = nil

        URLSession.shared.dataTask(with: request) { data, response, error in
            defer { semaphore.signal() }
            resultText = self.parseServerResponse(data: data)
        }.resume()

        _ = semaphore.wait(timeout: .now() + 35.0)
        return resultText
    }

    /// Generates and persists the JSON Schema specification required by `fm respond --schema`.
    private func ensureSchemaPath() throws -> String {
        if let existing = schemaPath, FileManager.default.fileExists(atPath: existing) {
            return existing
        }

        let tempDir = URL(fileURLWithPath: NSTemporaryDirectory()).appendingPathComponent("localgit")
        try FileManager.default.createDirectory(at: tempDir, withIntermediateDirectories: true)
        let fileURL = tempDir.appendingPathComponent("git_plan_schema.json")

        let schemaDict: [String: Any] = [
            "title": "GitPlan",
            "type": "object",
            "required": ["thought", "command", "explanation"],
            "additionalProperties": false,
            "properties": [
                "thought": [
                    "type": "string",
                    "description": "Analysis of the repository state and strategy"
                ],
                "command": [
                    "type": "string",
                    "description": "Exact git command(s) to execute in shell"
                ],
                "explanation": [
                    "type": "string",
                    "description": "User-friendly explanation of what the command does"
                ]
            ],
            "x-order": ["thought", "command", "explanation"]
        ]

        let data = try JSONSerialization.data(withJSONObject: schemaDict, options: [.prettyPrinted])
        try data.write(to: fileURL)

        self.schemaPath = fileURL.path
        return fileURL.path
    }

    /// Strips markdown code blocks (e.g. ```` ```json ... ``` ````) or isolates naked JSON objects.
    public func extractJsonPayload(from rawText: String) -> String {
        let cleaned = rawText.trimmingCharacters(in: .whitespacesAndNewlines)

        // Pattern 1: Markdown code fence ```json { ... } ```
        if let blockRegex = try? NSRegularExpression(pattern: "```(?:json)?\\s*(\\{.*?\\})\\s*```", options: [.dotMatchesLineSeparators]) {
            let nsStr = cleaned as NSString
            if let match = blockRegex.firstMatch(in: cleaned, range: NSRange(location: 0, length: nsStr.length)) {
                return nsStr.substring(with: match.range(at: 1)).trimmingCharacters(in: .whitespacesAndNewlines)
            }
        }

        // Pattern 2: Naked JSON braces { ... }
        if let nakedRegex = try? NSRegularExpression(pattern: "(\\{.*\\})", options: [.dotMatchesLineSeparators]) {
            let nsStr = cleaned as NSString
            if let match = nakedRegex.firstMatch(in: cleaned, range: NSRange(location: 0, length: nsStr.length)) {
                return nsStr.substring(with: match.range(at: 1)).trimmingCharacters(in: .whitespacesAndNewlines)
            }
        }

        return cleaned
    }

    /// Decodes a raw model string into a structured `GitPlan`.
    public func parseResponse(_ rawText: String) -> GitPlan {
        let jsonCandidate = extractJsonPayload(from: rawText)

        // Attempt JSON decoding
        if let data = jsonCandidate.data(using: .utf8),
           let plan = try? JSONDecoder().decode(GitPlan.self, from: data) {
            return GitPlan(
                thought: plan.thought.trimmingCharacters(in: .whitespacesAndNewlines),
                command: plan.command.trimmingCharacters(in: .whitespacesAndNewlines),
                explanation: plan.explanation.trimmingCharacters(in: .whitespacesAndNewlines),
                rawResponse: rawText
            )
        }

        // Heuristic fallback: search lines for raw git commands if JSON decoding failed
        let lines = rawText.components(separatedBy: .newlines).map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
        let gitLines = lines.filter { $0.hasPrefix("git ") || $0.contains("git ") }
        let cmd = gitLines.first ?? ""

        return GitPlan(
            thought: "Analyzing repository state and generating command",
            command: cmd,
            explanation: "Extracted git command directly from model response",
            rawResponse: rawText
        )
    }

    /// Spawns `/usr/bin/fm respond` with custom instructions, schema, and prompt.
    private func spawnCliProcess(prompt: String, instructions: String, schema: String? = nil) throws -> String {
        let process = Process()
        process.executableURL = URL(fileURLWithPath: binaryPath)

        var args = [
            "respond",
            "--no-stream",
            "-i", instructions
        ]
        if let s = schema {
            args.append(contentsOf: ["--schema", s])
        }
        args.append(prompt)

        process.arguments = args

        let outPipe = Pipe()
        let errPipe = Pipe()
        process.standardOutput = outPipe
        process.standardError = errPipe

        try process.run()
        process.waitUntilExit()

        let outData = outPipe.fileHandleForReading.readDataToEndOfFile()
        let errData = errPipe.fileHandleForReading.readDataToEndOfFile()

        let outStr = String(data: outData, encoding: .utf8)?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        let errStr = String(data: errData, encoding: .utf8)?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""

        if process.terminationStatus != 0 {
            throw NSError(domain: "AppleFMClient", code: Int(process.terminationStatus), userInfo: [
                NSLocalizedDescriptionKey: "fm command failed: \(errStr)"
            ])
        }

        return outStr
    }

    /// Internal dispatcher that prioritizes HTTP server mode before falling back to CLI process execution.
    private func executeFM(prompt: String, instructions: String, schema: String? = nil) throws -> String {
        if let serverResponse = try? queryServer(systemPrompt: instructions, userPrompt: prompt) {
            return serverResponse
        }
        return try spawnCliProcess(prompt: prompt, instructions: instructions, schema: schema)
    }

    /// Queries the model to generate a Git plan for the user's task.
    public func planAction(task: String, gitContext: String, sessionHistory: String? = nil) async throws -> GitPlan {
        let schema = try ensureSchemaPath()
        var sections: [String] = []

        if let history = sessionHistory, !history.isEmpty {
            sections.append("""
            Previous Session History:
            \(history)
            """)
        }

        sections.append("""
        Repository State:
        \(gitContext)
        """)

        sections.append("""
        User Task:
        \(task)

        Provide the exact git command to execute. Include your reasoning in the 'thought' field. Output JSON format:
        {"thought": "...", "command": "...", "explanation": "..."}
        """)

        let prompt = sections.joined(separator: "\n\n")
        let raw = try executeFM(prompt: prompt, instructions: AppleFMClient.defaultInstructions, schema: schema)
        return parseResponse(raw)
    }

    /// Queries the model to diagnose a command failure and return a corrective action.
    public func planRecovery(
        task: String,
        failedCommand: String,
        exitCode: Int32,
        output: String,
        gitContext: String
    ) async throws -> GitPlan {
        let schema = try ensureSchemaPath()
        let prompt = """
        An error occurred while attempting to satisfy the user goal.

        User Goal:
        \(task)

        Previous Command Attempted:
        \(failedCommand)

        Exit Code:
        \(exitCode)

        Terminal Output / Error:
        \(output.isEmpty ? "(no output)" : output)

        Updated Repository State:
        \(gitContext)

        Diagnose the exact root cause of this failure in 'thought' and provide the corrected git command in 'command' to fix the issue and achieve the goal. Output JSON format:
        {"thought": "...", "command": "...", "explanation": "..."}
        """
        let raw = try executeFM(prompt: prompt, instructions: AppleFMClient.defaultInstructions, schema: schema)
        return parseResponse(raw)
    }

    /// Prompts the model to synthesize raw terminal output into a friendly summary for the user.
    public func synthesizeOutput(
        task: String,
        executedCommand: String,
        exitCode: Int32,
        rawTerminalOutput: String
    ) async throws -> String {
        let prompt = """
        User Goal:
        \(task)

        Executed Command:
        \(executedCommand) (exit code \(exitCode))

        Terminal Output:
        \(rawTerminalOutput.isEmpty ? "(Command completed successfully with empty output)" : rawTerminalOutput)

        Explain clearly what was done and the result to show to the user.
        """
        do {
            let response = try executeFM(prompt: prompt, instructions: AppleFMClient.outputSynthesisInstructions)
            let trimmed = response.trimmingCharacters(in: .whitespacesAndNewlines)
            if !trimmed.isEmpty {
                return trimmed
            }
        } catch {
            // Fallback gracefully if model synthesis fails
        }

        if !rawTerminalOutput.isEmpty {
            return rawTerminalOutput
        }
        return "Command executed successfully."
    }
}
